SVGS = ['<svg viewBox="0 0 700 240" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="240" rx="12" fill="#f8fafc" stroke="#cbd5e1" stroke-width="2"/>\n  <text x="350" y="26" font-size="14" font-weight="bold" fill="#0f172a" text-anchor="middle">RİVAYET (ME\'SÛR) VE DİRAYET (RE\'Y) TEFSİRLERİNİN MUKAYESESİ</text>\n  <rect x="20" y="44" width="215" height="176" rx="8" fill="#dbeafe" stroke="#2563eb" stroke-width="2"/>\n  <text x="127" y="66" font-size="12" font-weight="bold" fill="#1e40af" text-anchor="middle">Rivayet (Me\'sûr) Tefsiri</text>\n  <text x="127" y="90" font-size="10.5" fill="#1e3a8a" text-anchor="middle">• Naklî delillere (Ayet, Hadis,</text>\n  <text x="127" y="106" font-size="10.5" fill="#1e3a8a" text-anchor="middle">Sahabe ve Tâbiîn kavli) dayanır</text>\n  <text x="127" y="130" font-size="10.5" fill="#1e3a8a" text-anchor="middle">• Senet (râvi zinciri) aktarır</text>\n  <text x="127" y="154" font-size="10.5" font-weight="bold" fill="#1d4ed8" text-anchor="middle">Örnek Müfessirler:</text>\n  <text x="127" y="174" font-size="10" fill="#334155" text-anchor="middle">Taberî · İbn Kesîr · Süyûtî</text>\n  <text x="127" y="194" font-size="10" fill="#334155" text-anchor="middle">Vâhidî (Esbâbü\'n-Nüzûl)</text>\n  <rect x="245" y="44" width="210" height="176" rx="8" fill="#dcfce7" stroke="#16a34a" stroke-width="2"/>\n  <text x="350" y="66" font-size="12" font-weight="bold" fill="#166534" text-anchor="middle">Ortak Yönler (Benzerlikler)</text>\n  <text x="350" y="92" font-size="10.5" fill="#14532d" text-anchor="middle">• İlahi muradı anlama gayesi</text>\n  <text x="350" y="116" font-size="10.5" fill="#14532d" text-anchor="middle">• Kur\'an ve Sünnet bütünlüğü</text>\n  <text x="350" y="140" font-size="10.5" fill="#14532d" text-anchor="middle">• Nüzul sebeplerini gözetme</text>\n  <text x="350" y="164" font-size="10.5" fill="#14532d" text-anchor="middle">• Arap dili kurallarına uyum</text>\n  <text x="350" y="190" font-size="10" font-weight="bold" fill="#15803d" text-anchor="middle">Mushaf Tertibine Göre Tefsir</text>\n  <rect x="465" y="44" width="215" height="176" rx="8" fill="#fef3c7" stroke="#d97706" stroke-width="2"/>\n  <text x="572" y="66" font-size="12" font-weight="bold" fill="#92400e" text-anchor="middle">Dirayet (Re\'y) Tefsiri</text>\n  <text x="572" y="90" font-size="10.5" fill="#78350f" text-anchor="middle">• Nakil yanında dil, belâgat,</text>\n  <text x="572" y="106" font-size="10.5" fill="#78350f" text-anchor="middle">fıkıh, kelam ve içtihada dayanır</text>\n  <text x="572" y="130" font-size="10.5" fill="#78350f" text-anchor="middle">• Güncel meselelere çözüm üretir</text>\n  <text x="572" y="154" font-size="10.5" font-weight="bold" fill="#b45309" text-anchor="middle">Örnek Müfessirler:</text>\n  <text x="572" y="174" font-size="10" fill="#334155" text-anchor="middle">Râzî · Beyzâvî · Ebüssuûd Efendi</text>\n  <text x="572" y="194" font-size="10" fill="#334155" text-anchor="middle">Elmalılı M. Hamdi Yazır</text>\n</svg>', '<svg viewBox="0 0 700 240" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="240" rx="12" fill="#fdfbf7" stroke="#d6d3d1" stroke-width="2"/>\n  <text x="350" y="26" font-size="14" font-weight="bold" fill="#292524" text-anchor="middle">YÖNELİMLERİNE GÖRE BAŞLICA TEFSİR ÇEŞİTLERİ</text>\n  <rect x="20" y="44" width="320" height="82" rx="8" fill="#eff6ff" stroke="#2563eb" stroke-width="1.8"/>\n  <text x="180" y="66" font-size="12" font-weight="bold" fill="#1d4ed8" text-anchor="middle">1. Fıkhî (Ahkâm) Tefsir</text>\n  <text x="180" y="88" font-size="10.5" fill="#1e3a8a" text-anchor="middle">İbadet, hukuk ve muamelat ayetlerinden hüküm çıkarır.</text>\n  <text x="180" y="108" font-size="10" font-weight="bold" fill="#1e40af" text-anchor="middle">Temsilciler: Cassâs, İbnü\'l-Arabî, Kurtubî</text>\n  <rect x="360" y="44" width="320" height="82" rx="8" fill="#f3e8ff" stroke="#9333ea" stroke-width="1.8"/>\n  <text x="520" y="66" font-size="12" font-weight="bold" fill="#6b21a8" text-anchor="middle">2. İşârî (Tasavvufi) Tefsir</text>\n  <text x="520" y="88" font-size="10.5" fill="#581c87" text-anchor="middle">Zahirî anlam yanında ayetlerin ruhî-ahlaki işaretlerini açıklar.</text>\n  <text x="520" y="108" font-size="10" font-weight="bold" fill="#6b21a8" text-anchor="middle">Temsilciler: Tüsterî, Kuşeyrî, İsmail Hakkı Bursevî</text>\n  <rect x="20" y="140" width="320" height="82" rx="8" fill="#ecfdf5" stroke="#10b981" stroke-width="1.8"/>\n  <text x="180" y="162" font-size="12" font-weight="bold" fill="#047857" text-anchor="middle">3. Konulu (Mevzûî) Tefsir</text>\n  <text x="180" y="184" font-size="10.5" fill="#065f46" text-anchor="middle">Belirli bir kavramla ilgili tüm ayetleri bir arada inceler.</text>\n  <text x="180" y="204" font-size="10" font-weight="bold" fill="#047857" text-anchor="middle">Kur\'an bütünlüğü içinde tematik araştırma sağlar.</text>\n  <rect x="360" y="140" width="320" height="82" rx="8" fill="#fef3c7" stroke="#d97706" stroke-width="1.8"/>\n  <text x="520" y="162" font-size="12" font-weight="bold" fill="#92400e" text-anchor="middle">4. İlmî (Bilimsel) Tefsir</text>\n  <text x="520" y="184" font-size="10.5" fill="#78350f" text-anchor="middle">Kevni (evren ve tabiat) ayetleri bilim verileriyle yorumlar.</text>\n  <text x="520" y="204" font-size="10" font-weight="bold" fill="#92400e" text-anchor="middle">Kesinleşmemiş bilimsel teorilerle ayet sınırlandırılmaz.</text>\n</svg>', '<svg viewBox="0 0 700 220" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="220" rx="12" fill="#f8fafc" stroke="#94a3b8" stroke-width="2"/>\n  <text x="350" y="28" font-size="14" font-weight="bold" fill="#0f172a" text-anchor="middle">TEFSİR TARİHİNDE ÖRNEK ALİMLER VE BAŞLICA ESERLERİ</text>\n  <rect x="20" y="48" width="210" height="150" rx="8" fill="#eff6ff" stroke="#3b82f6" stroke-width="2"/>\n  <text x="125" y="72" font-size="12" font-weight="bold" fill="#1d4ed8" text-anchor="middle">Vâhidî (ö. 1076)</text>\n  <text x="125" y="96" font-size="10.5" fill="#1e3a8a" text-anchor="middle">• Eseri: Esbâbü\'n-Nüzûl</text>\n  <text x="125" y="118" font-size="10.5" fill="#1e3a8a" text-anchor="middle">• el-Vecîz, el-Vasît, el-Basît</text>\n  <text x="125" y="142" font-size="10" fill="#334155" text-anchor="middle">Ayetlerin iniş sebeplerini</text>\n  <text x="125" y="158" font-size="10" fill="#334155" text-anchor="middle">derleyen öncü rivayet âlimi</text>\n  <rect x="245" y="48" width="210" height="150" rx="8" fill="#fefce8" stroke="#eab308" stroke-width="2"/>\n  <text x="350" y="72" font-size="12" font-weight="bold" fill="#a16207" text-anchor="middle">Ebüssuûd Efendi (ö. 1574)</text>\n  <text x="350" y="96" font-size="10.5" fill="#713f12" text-anchor="middle">• Eseri: İrşâdü\'l-Akli\'s-Selîm</text>\n  <text x="350" y="118" font-size="10.5" fill="#713f12" text-anchor="middle">• Unvanı: Hatîbü\'l-Müfessirîn</text>\n  <text x="350" y="142" font-size="10" fill="#334155" text-anchor="middle">Kur\'an\'ın eşsiz belâgatını ve</text>\n  <text x="350" y="158" font-size="10" fill="#334155" text-anchor="middle">fıkhî inceliklerini açıklayan dirayet</text>\n  <rect x="470" y="48" width="210" height="150" rx="8" fill="#f3e8ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="575" y="72" font-size="12" font-weight="bold" fill="#6b21a8" text-anchor="middle">İsmail Hakkı Bursevî (ö. 1725)</text>\n  <text x="575" y="96" font-size="10.5" fill="#581c87" text-anchor="middle">• Eseri: Rûhu\'l-Beyân</text>\n  <text x="575" y="118" font-size="10.5" fill="#581c87" text-anchor="middle">• Yöntemi: İşârî ve Vaaz Tefsiri</text>\n  <text x="575" y="142" font-size="10" fill="#334155" text-anchor="middle">Zahirî tefsir ile tasavvufi-ahlaki</text>\n  <text x="575" y="158" font-size="10" fill="#334155" text-anchor="middle">hikmetleri birleştiren eser</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get('bolumler', [])):
        if i < len(SVGS):
            b['gorsel'] = SVGS[i]
